import {bank,languages,notes} from './content.js';
import {key,makeLesson,schedule,finishRound,questions} from './engine.js';
import {makeBoards,emptyMatch,selectMatch} from './matching.js';
const root=document.querySelector('#app');
const defaults={languages:['es','fr','de'],noun:4,verb:2,grammar:1,sentence:2};
let data={settings:defaults,history:{},sessions:[]},storageError=false;
try{const stored=JSON.parse(localStorage.getItem('perlingo-v1'));if(stored?.settings&&stored?.history&&Array.isArray(stored.sessions))data=stored;}catch{storageError=true;}
let view='home',lesson=[],index=0,round=1,streak=0,boards=[],boardIndex=0,match=emptyMatch(),mistakes=0,answers=0,correct=0,first={},started=0,result=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('perlingo-v1',JSON.stringify(data));}catch{storageError=true;}}
const due=()=>Object.entries(data.history).filter(([k,v])=>data.settings.languages.includes(k.split(':')[1])&&v.due<=Date.now()).length;
const duration=ms=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
function shell(content){const active=['study','quiz','round'].includes(view);root.innerHTML=`<div class="shell"><header class="top"><button class="brand" data-action="home" aria-label="Perlingo home">perlingo<span>.</span></button><nav>${active?'<button class="plain" data-action="home">Exit session</button>':`<button class="plain icon" data-action="settings" aria-label="Settings" title="Settings"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--bg)"/><circle cx="15" cy="17" r="3" fill="var(--bg)"/></svg></button>`}</nav></header>${storageError?'<p class="error">Browser storage is unavailable. Progress may not survive a reload.</p>':''}<main>${content}</main>${active?'':`<footer class="footer"><button class="plain" data-action="history">Progress</button><span>${data.settings.languages.map(l=>languages[l].name).join(' / ')}</span></footer>`}</div>`;}
function steps(){return '';}
function render(){if(view==='home')home();if(view==='study')study();if(view==='quiz')quiz();if(view==='round')roundEnd();if(view==='results')results();if(view==='history')history();if(view==='settings')settings();}
function translations(item){return `<div class="translations">${data.settings.languages.map(l=>`<article class="translation"><span class="badge">${languages[l].name}</span><div class="translation-value"><h3>${esc(item[l])}</h3><button data-speak="${l}" aria-label="Listen in ${languages[l].name}" title="Listen"><svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5Zm4 4a5 5 0 0 1 0 6m3-9a9 9 0 0 1 0 12"/></svg></button></div></article>`).join('')}</div><p id="audio-status" class="muted" role="status"></p>`;}
function home(){const preview=makeLesson(bank,data.settings,data.history),item=preview[0];shell(item?`<section class="concept"><div class="study-head"><span class="eyebrow">Learn</span><span class="counter">01 <span>/ ${String(preview.length).padStart(2,'0')}</span></span></div><div class="concept-body"><h1 class="word">${esc(item.en)}</h1>${translations(item)}</div><div class="actions"><span class="hint">One concept. ${data.settings.languages.length===1?'One language.':data.settings.languages.length+' languages.'}</span><button class="primary" data-action="start">${preview.length===1?'Begin recall':'Next concept'} <span>→</span></button></div></section>`:`<section class="empty center"><div class="eyebrow">All caught up</div><h1>Let it settle.</h1><p class="muted">Return when your next reviews are due, or adjust your learning routine.</p><button class="secondary" data-action="settings">Learning settings</button></section>`);}
function study(){const item=lesson[index];shell(`<section class="concept"><div class="study-head"><span class="eyebrow">Learn</span><span class="counter">${String(index+1).padStart(2,'0')} <span>/ ${String(lesson.length).padStart(2,'0')}</span></span></div><div class="concept-body"><h1 class="word">${esc(item.en)}</h1>${translations(item)}<details class="note"><summary>Usage note</summary><p>${notes[item.type]}</p></details></div><div class="actions"><button class="plain" data-action="prev" ${index===0?'disabled':''}>← Back</button><button class="primary" data-action="next">${index===lesson.length-1?'Begin recall':'Next concept'} <span>→</span></button></div></section>`);}
function settings(){shell(`<section class="settings"><button class="plain back" data-action="home">← Back to learning</button><h1>Your routine.</h1><p class="muted">Set it once. Every session follows your lead.</p><div class="settings-section"><h2>Languages</h2><div class="langs">${Object.entries(languages).map(([id,l])=>`<button class="lang ${data.settings.languages.includes(id)?'selected':''}" data-lang="${id}" aria-pressed="${data.settings.languages.includes(id)}">${l.name}<span>${data.settings.languages.includes(id)?'✓':'+'}</span></button>`).join('')}</div></div><details class="routine"><summary>Session structure <span>Advanced</span></summary><p class="muted">Default concept counts for every session. Due reviews are always included, even when they exceed these targets.</p><div class="counts">${[['noun','Nouns',16],['verb','Verbs',8],['grammar','Grammar',4],['sentence','Sentences',6]].map(([id,label,max])=>`<label>${label}<input aria-label="${label}" data-setting="${id}" type="number" min="0" max="${max}" value="${data.settings[id]}"></label>`).join('')}</div><p class="muted">Changes apply to future sessions and save automatically on this browser.</p></details><div class="settings-section"><div class="stat"><span>Finish line</span><span>3 consecutive perfect rounds</span></div></div><p class="hint">Settings and progress are stored on this browser.</p></section>`);}
function startRound(){boards=makeBoards(lesson,data.settings.languages);boardIndex=0;mistakes=0;match=emptyMatch();view='quiz';render();}
function quiz(){const board=boards[boardIndex],done=match.matched.length===board.left.length;
 const tile=(item,side)=>{const matched=match.matched.includes(item.id),selected=match[side]===item.id,wrong=match.last&&!match.last.correct&&match.last[side]===item.id;return `<button class="match-tile ${matched?'matched':''} ${selected?'selected':''} ${wrong?'mismatch':''}" data-match-side="${side}" data-match-id="${item.id}" aria-pressed="${selected}" ${matched?'disabled':''}><span>${esc(side==='left'?item.en:item[board.lang])}</span><span class="match-mark" aria-hidden="true">${matched?'✓':selected?'•':wrong?'×':''}</span></button>`;};
 shell(`<section class="quiz matching"><div class="study-head"><span class="eyebrow">Recall · Round ${round}</span><span class="pill">${'●'.repeat(streak)}${'○'.repeat(3-streak)} &nbsp; ${streak}/3 perfect</span></div><div class="match-title"><h1>Find the pairs.</h1><span class="counter">${boardIndex+1} / ${boards.length}</span></div><p class="muted">Tap a word, then its translation.</p><div class="match-board"><div class="match-column" role="group" aria-label="English words"><h2 class="badge">English</h2>${board.left.map(i=>tile(i,'left')).join('')}</div><div class="match-column" role="group" aria-label="${languages[board.lang].name} translations"><h2 class="badge">${languages[board.lang].name}</h2>${board.right.map(i=>tile(i,'right')).join('')}</div></div><div class="match-status" role="status" aria-live="polite">${done?'Board complete.':match.last?match.last.correct?'Matched.':'Not a match. Try again — this round won’t count as perfect.':match.left||match.right?'Now choose its match.':'Choose from either column.'}</div><div class="actions"><span class="hint">${match.matched.length} / ${board.left.length} pairs matched</span>${done?`<button class="primary" data-action="next-board">${boardIndex===boards.length-1?'Finish round':'Next board'} <span>→</span></button>`:'<span class="hint">'+(mistakes?'Practice round':'No mistakes so far')+'</span>'}</div></section>`);
}
function playMatch(side,id){const board=boards[boardIndex];if(!board[side]?.some(item=>item.id===id))return;
 const outcome=selectMatch(match,side,id);match=outcome.state;
 if(outcome.attempt){const attempt=outcome.attempt;answers++;correct+=Number(attempt.correct);mistakes+=Number(!attempt.correct);
  // A wrong pairing implicates both concepts; later elimination cannot erase it.
  for(const involved of new Set([attempt.left,attempt.right])){const k=key(involved,board.lang);if(!(k in first))first[k]=attempt.correct;}
 }
 render();
 const focus=match.matched.length===board.left.length?root.querySelector('[data-action="next-board"]'):root.querySelector(`[data-match-side="${side}"][data-match-id="${id}"]:not(:disabled)`)||root.querySelector('[data-match-side]:not(:disabled)');focus?.focus({preventScroll:true});
}
function roundEnd(){shell(`<section class="card quiz center"><div class="eyebrow">Round ${round} complete</div><h1>${mistakes?'A little more practice.':'A perfect round.'}</h1><p class="muted">${mistakes?`${mistakes} missed. Your consecutive streak starts again.`:`${streak} of 3 consecutive perfect rounds.`}</p><h1 class="streak-dots">${'● '.repeat(streak)}${'○ '.repeat(3-streak)}</h1><button class="primary" data-action="another">Next round →</button><p class="muted" style="margin-top:20px">Every round reshuffles concepts and languages.</p></section>`);}
function complete(){const now=Date.now();for(const q of questions(lesson,data.settings.languages)){const k=key(q.item.id,q.lang);const previous=data.history[k];if(!previous||previous.due<=now)data.history[k]=schedule(previous,first[k],now);}result={date:new Date(now).toISOString(),concepts:lesson.length,pairs:lesson.length*data.settings.languages.length,rounds:round,accuracy:Math.round(correct/answers*100),duration:now-started,languages:[...data.settings.languages]};data.sessions.push(result);save();view='results';render();}
function results(){shell(`<section class="card quiz center"><div class="eyebrow">Session ${String(data.sessions.length).padStart(3,'0')} · Complete</div><h1>Session complete.</h1><p class="muted">Three perfect rounds, back to back. Nicely done.</p><div class="metrics"><div class="metric"><strong>${result.accuracy}%</strong><span class="muted">session accuracy</span></div><div class="metric"><strong>${duration(result.duration)}</strong><span class="muted">study time</span></div><div class="metric"><strong>${result.rounds}</strong><span class="muted">rounds</span></div></div><p class="muted">${result.pairs} translations practiced. Reviews are scheduled per language.<br>Come back tomorrow to see what you remember.</p><button class="primary" data-action="home">Back to practice →</button></section>`);}
function history(){shell(`<div class="intro"><div><div class="eyebrow">Your learning journal</div><h1>Small sessions add up.</h1><p class="muted">Your progress lives in this browser. Export a backup to keep it.</p></div><button class="secondary" data-action="export">Export progress ↓</button></div><div class="metrics"><div class="metric"><strong>${data.sessions.length}</strong>completed sessions</div><div class="metric"><strong>${Object.keys(data.history).length}</strong>language pairs studied</div><div class="metric"><strong>${due()}</strong>pairs due for review</div></div><div class="card"><h2>Session history</h2>${data.sessions.length?[...data.sessions].reverse().map(s=>`<div class="history-row"><span>${new Date(s.date).toLocaleDateString()}<br><small class="muted">${s.languages.map(l=>languages[l].name).join(' · ')}</small></span><span>${s.pairs} translations<br><small class="muted">${s.accuracy}% · ${s.rounds} rounds · ${duration(s.duration)}</small></span></div>`).join(''):'<p class="muted">Your first session starts a new story. Complete a challenge to see it here.</p>'}</div>`);}
root.addEventListener('input',e=>{const id=e.target.dataset.setting;if(id){data.settings[id]=Math.max(0,Math.min(Number(e.target.max),Math.floor(Number(e.target.value)||0)));save();}});
root.addEventListener('change',e=>{const id=e.target.dataset.setting;if(id){data.settings[id]=Math.max(0,Math.min(Number(e.target.max),Math.floor(Number(e.target.value)||0)));save();}});
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=b.dataset.action;if(b.dataset.lang){const l=b.dataset.lang;const list=data.settings.languages;if(list.includes(l)){if(list.length>1)data.settings.languages=list.filter(x=>x!==l);}else data.settings.languages=Object.keys(languages).filter(x=>list.includes(x)||x===l);save();render();return;}
if(b.dataset.speak){const status=document.querySelector('#audio-status');if(!('speechSynthesis'in window)){status.textContent='Pronunciation is unavailable in this browser.';return;}const l=b.dataset.speak;const item=view==='home'?makeLesson(bank,data.settings,data.history)[0]:lesson[index];const u=new SpeechSynthesisUtterance(item[l]);u.lang=languages[l].locale;u.rate=.8;u.onerror=()=>status.textContent='Audio is unavailable. Check your browser’s installed voices.';speechSynthesis.cancel();speechSynthesis.speak(u);return;}
if(b.dataset.matchSide){playMatch(b.dataset.matchSide,b.dataset.matchId);return;}
if(a==='home'||a==='history'||a==='settings'){if(['study','quiz','round'].includes(view)&&!confirm('Leave this session? This session’s unfinished progress will not be saved.'))return;view=a;render();return;}
if(a==='start'){lesson=makeLesson(bank,data.settings,data.history);index=lesson.length>1?1:0;round=1;streak=0;answers=0;correct=0;first={};started=Date.now();if(lesson.length===1)startRound();else{view='study';render();}}if(a==='prev'){index--;render();}if(a==='next'){if(index<lesson.length-1){index++;render();}else startRound();}if(a==='next-board'&&match.matched.length===boards[boardIndex].left.length){if(boardIndex<boards.length-1){boardIndex++;match=emptyMatch();render();}else{streak=finishRound(streak,mistakes);if(streak===3)complete();else{view='round';render();}}}if(a==='another'){round++;startRound();}if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='perlingo-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});

render();
